class Solution:
    def primeSum(self, n: int) -> int:
        def rev(x):
            y = 0
            while x:
                y = y * 10 + x % 10
                x //= 10
            return y
        def is_prime(v):
            if v < 2:
                return False
            d = 2
            while d * d <= v:
                if v % d == 0:
                    return False
                d += 1
            return True
        r = rev(n)
        lo, hi = min(n, r), max(n, r)
        return sum(v for v in range(lo, hi + 1) if is_prime(v))

