class Solution {
public:
    int primeSum(int n) {
        auto rev = [](int x) {
            long long y = 0;
            while (x) { y = y * 10 + x % 10; x /= 10; }
            return (int)y;
        };
        auto isPrime = [](int v) {
            if (v < 2) return false;
            for (int d = 2; (long long)d * d <= v; ++d)
                if (v % d == 0) return false;
            return true;
        };
        int r = rev(n);
        int lo = std::min(n, r), hi = std::max(n, r);
        long long ans = 0;
        for (int v = lo; v <= hi; ++v)
            if (isPrime(v)) ans += v;
        return (int)ans;
    }
};

