class Solution {
    public int primeSum(int n) {
        int r = 0, x = n;
        while (x > 0) { r = r * 10 + x % 10; x /= 10; }
        int lo = Math.min(n, r), hi = Math.max(n, r);
        long ans = 0;
        for (int v = lo; v <= hi; v++)
            if (isPrime(v)) ans += v;
        return (int) ans;
    }
    private boolean isPrime(int v) {
        if (v < 2) return false;
        for (int d = 2; (long) d * d <= v; d++)
            if (v % d == 0) return false;
        return true;
    }
}

