class Solution {
    public int primeSum(int n) {
        final int LIMIT = 1000;
        boolean[] sieve = new boolean[LIMIT + 1];
        java.util.Arrays.fill(sieve, 2, LIMIT + 1, true);
        for (int i = 2; i * i <= LIMIT; i++)
            if (sieve[i])
                for (int j = i * i; j <= LIMIT; j += i)
                    sieve[j] = false;
        int r = 0, x = n;
        while (x > 0) { r = r * 10 + x % 10; x /= 10; }
        int lo = Math.min(n, r), hi = Math.max(n, r);
        long ans = 0;
        for (int v = lo; v <= hi; v++)
            if (sieve[v]) ans += v;
        return (int) ans;
    }
}

